static EXPECTED_SCHEMA_V6_FINGERPRINT: LazyLock<Result<String, String>> = LazyLock::new(|| {
    let mut connection = Connection::open_in_memory().map_err(|error| error.to_string())?;
    connection
        .execute_batch(SCHEMA_V5)
        .map_err(|error| error.to_string())?;
    let transaction = connection
        .transaction()
        .map_err(|error| error.to_string())?;
    transaction
        .execute_batch(
            "DROP TRIGGER immutable_schema_metadata_update;
             DROP TRIGGER immutable_schema_metadata_delete;
             ALTER TABLE schema_metadata RENAME TO schema_metadata_v5;",
        )
        .map_err(|error| error.to_string())?;
    transaction
        .execute_batch(SCHEMA_METADATA_V6)
        .map_err(|error| error.to_string())?;
    transaction
        .execute(
            "INSERT INTO schema_metadata (
                singleton, product, schema_version, schema_artifact_digest, initialized_at
             )
             SELECT singleton, product, 6, ?1, initialized_at
             FROM schema_metadata_v5",
            [SCHEMA_V6_ARTIFACT_DIGEST],
        )
        .map_err(|error| error.to_string())?;
    transaction
        .execute("DROP TABLE schema_metadata_v5", [])
        .map_err(|error| error.to_string())?;
    transaction
        .execute_batch(SCHEMA_METADATA_V6_TRIGGERS)
        .map_err(|error| error.to_string())?;
    transaction
        .execute_batch(SCHEMA_V5_TO_V6_RUNTIME_LEDGER)
        .map_err(|error| error.to_string())?;
    transaction
        .pragma_update(None, "user_version", 6)
        .map_err(|error| error.to_string())?;
    let fingerprint = schema_fingerprint(&transaction).map_err(|error| error.to_string())?;
    transaction.commit().map_err(|error| error.to_string())?;
    Ok(fingerprint)
});
static EXPECTED_SCHEMA_V7_FINGERPRINT: LazyLock<Result<String, String>> =
    LazyLock::new(expected_schema_v7_fingerprint);

fn expected_schema_v7_fingerprint() -> Result<String, String> {
    let mut connection = Connection::open_in_memory().map_err(|error| error.to_string())?;
    connection
        .execute_batch(SCHEMA_V5)
        .map_err(|error| error.to_string())?;
    {
        let transaction = connection
            .transaction()
            .map_err(|error| error.to_string())?;
        transaction
            .execute_batch(
                "DROP TRIGGER immutable_schema_metadata_update;
                 DROP TRIGGER immutable_schema_metadata_delete;
                 ALTER TABLE schema_metadata RENAME TO schema_metadata_v5;",
            )
            .map_err(|error| error.to_string())?;
        transaction
            .execute_batch(SCHEMA_METADATA_V6)
            .map_err(|error| error.to_string())?;
        transaction
            .execute(
                "INSERT INTO schema_metadata (
                    singleton, product, schema_version, schema_artifact_digest, initialized_at
                 )
                 SELECT singleton, product, 6, ?1, initialized_at
                 FROM schema_metadata_v5",
                [SCHEMA_V6_ARTIFACT_DIGEST],
            )
            .map_err(|error| error.to_string())?;
        transaction
            .execute("DROP TABLE schema_metadata_v5", [])
            .map_err(|error| error.to_string())?;
        transaction
            .execute_batch(SCHEMA_METADATA_V6_TRIGGERS)
            .map_err(|error| error.to_string())?;
        transaction
            .execute_batch(SCHEMA_V5_TO_V6_RUNTIME_LEDGER)
            .map_err(|error| error.to_string())?;
        transaction
            .pragma_update(None, "user_version", 6)
            .map_err(|error| error.to_string())?;
        transaction.commit().map_err(|error| error.to_string())?;
    }
    let transaction = connection
        .transaction()
        .map_err(|error| error.to_string())?;
    transaction
        .execute_batch(
            "DROP TRIGGER immutable_schema_metadata_update;
             DROP TRIGGER immutable_schema_metadata_delete;
             ALTER TABLE schema_metadata RENAME TO schema_metadata_v6;",
        )
        .map_err(|error| error.to_string())?;
    transaction
        .execute_batch(SCHEMA_METADATA_V7)
        .map_err(|error| error.to_string())?;
    transaction
        .execute(
            "INSERT INTO schema_metadata (
                singleton, product, schema_version, schema_artifact_digest, initialized_at
             )
             SELECT singleton, product, 7, ?1, initialized_at
             FROM schema_metadata_v6",
            [SCHEMA_V7_ARTIFACT_DIGEST],
        )
        .map_err(|error| error.to_string())?;
    transaction
        .execute("DROP TABLE schema_metadata_v6", [])
        .map_err(|error| error.to_string())?;
    transaction
        .execute_batch(SCHEMA_METADATA_V7_TRIGGERS)
        .map_err(|error| error.to_string())?;
    transaction
        .execute_batch(SCHEMA_V6_TO_V7_RUNTIME_DEPENDENCIES)
        .map_err(|error| error.to_string())?;
    transaction
        .pragma_update(None, "user_version", 7)
        .map_err(|error| error.to_string())?;
    let fingerprint = schema_fingerprint(&transaction).map_err(|error| error.to_string())?;
    transaction.commit().map_err(|error| error.to_string())?;
    Ok(fingerprint)
}

/// Exact predecessor schema version retained for the governed Gen4-to-C2
/// sequential migration.  Gen4 migration code must use this literal pin and
/// never the moving current-schema constant.
const SCHEMA_V8_VERSION: i64 = 8;

/// The only ordinary schema version understood by this crate.
pub const SCHEMA_VERSION: i64 = 9;

/// Exact schema-v9 projection migration surface.
///
/// The functions are crate-private because schema compatibility is not
/// migration authority.  A Store-owned installation or migration route must
/// first obtain the linear verified-source brand and then earn the
/// installation-owned pending-projection permit; no external caller can turn
/// an arbitrary SQLite path into C2 standing, B/G authority, a physical Store
/// generation, or a writer session.
pub mod schema {
    use super::*;

    /// Closed successful result of the exact sequential migration.
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    pub enum C2SchemaV9Projection {
        /// Exact schema-v8 bytes and state were verified immediately before
        /// the atomic schema-v9 projection migration.
        SequentialV8ToV9,
    }

    /// Linear proof that one exact on-disk schema-v8 Store was verified for
    /// the sequential projection migration.  Fields and construction remain
    /// crate-private; this value carries no signer or mutation standing.
    #[derive(Debug)]
    pub(crate) struct VerifiedC2SchemaV8ToV9Sequential {
        path: PathBuf,
        device: u64,
        inode: u64,
        logical_state_digest: String,
    }

    /// Verify the exact pinned schema-v8 source and return a non-cloneable
    /// brand for that same file identity and logical state.
    pub(crate) fn verify_c2_schema_v8_to_v9_sequential(
        path: impl AsRef<Path>,
    ) -> Result<VerifiedC2SchemaV8ToV9Sequential, StoreError> {
        let path = path.as_ref();
        if !path.is_file() || std::fs::metadata(path)?.len() == 0 {
            return Err(StoreError::NotInitialized(path.to_path_buf()));
        }
        let path = std::fs::canonicalize(path)?;
        let metadata = std::fs::metadata(&path)?;
        let connection = Connection::open_with_flags(
            &path,
            OpenFlags::SQLITE_OPEN_READ_ONLY | OpenFlags::SQLITE_OPEN_NO_MUTEX,
        )?;
        connection.busy_timeout(std::time::Duration::from_secs(5))?;
        connection.pragma_update(None, "query_only", "ON")?;
        validate_v8_upgrade_source_connection(&connection)?;
        let logical_state_digest = v8_logical_state_digest(&connection)?;
        Ok(VerifiedC2SchemaV8ToV9Sequential {
            path,
            device: metadata.dev(),
            inode: metadata.ino(),
            logical_state_digest,
        })
    }

    /// Consume one exact installation-owned pending-projection permit and
    /// atomically install the complete schema-v9 projection.  The transaction
    /// creates only rebuildable projection/index tables and cannot create B/G,
    /// a physical generation, signer standing/currentness, or a writer
    /// session.  The permit is deliberately not constructible in product code
    /// until the ordered Store-owned installation driver exists.
    #[cfg(test)]
    pub(crate) fn apply_c2_schema_v8_to_v9<Mode>(
        permit: crate::store_generation::install::C2PendingSqlProjectionPermitV1<Mode>,
    ) -> Result<C2SchemaV9Projection, StoreError> {
        let verified = permit.into_verified_source();
        let metadata = std::fs::metadata(&verified.path)?;
        if (metadata.dev(), metadata.ino()) != (verified.device, verified.inode) {
            return Err(StoreError::Invariant(
                "schema-v8 migration source file identity changed after verification".into(),
            ));
        }

        let mut connection = Connection::open_with_flags(
            &verified.path,
            OpenFlags::SQLITE_OPEN_READ_WRITE | OpenFlags::SQLITE_OPEN_NO_MUTEX,
        )?;
        configure_connection(&connection, false)?;
        validate_v8_upgrade_source_connection(&connection)?;
        if v8_logical_state_digest(&connection)? != verified.logical_state_digest {
            return Err(StoreError::Invariant(
                "schema-v8 migration source changed after exact verification".into(),
            ));
        }
        if sha256_digest(SCHEMA_V8_TO_V9_C2_STORE_GENERATION.as_bytes())
            != SCHEMA_V8_TO_V9_C2_STORE_GENERATION_SHA256
            || sha256_digest(SCHEMA_V9_C2_SIGNER_LINEAGE.as_bytes())
                != SCHEMA_V9_C2_SIGNER_LINEAGE_SHA256
        {
            return Err(StoreError::Invariant(
                "compiled C2 schema-v9 projection migration identity mismatch".into(),
            ));
        }

        let transaction = connection.transaction_with_behavior(TransactionBehavior::Immediate)?;
        upgrade_v8_to_v9_c2_schema(&transaction)?;
        transaction.commit()?;

        let store = Store {
            connection,
            path: Some(verified.path.clone()),
            writer_key: writer_session::writer_key_for_path(Some(&verified.path)),
            v7_authority_migration: None,
            runtime_authority_initialization_candidate: false,
        };
        store.validate()?;
        verify_empty_c2_schema_v9_projection(&store.connection)?;
        Ok(C2SchemaV9Projection::SequentialV8ToV9)
    }
}

/// Exact sidecar schema emitted by the official restore path.  The sidecar
/// declares the restore act without changing the restored Store bytes.
pub const RESTORE_DECLARATION_SCHEMA: &str = "nq.restore_declaration.v1";

/// Hard ceiling for one page returned through the public read model helpers.
pub const MAX_PUBLIC_QUERY_ROWS: u32 = 1_000;

/// Storage-wide ceiling for any one canonical JSON document.
pub const MAX_STORED_JSON_BYTES: usize = nq_protocol::MAX_RESPONSE_FRAME_BYTES;

/// A materialization plan may contain the previous and desired bounded
/// admission locks plus recovery metadata.
const MAX_BINDING_MATERIALIZATION_BYTES: usize = 3 * 1_048_576;

/// Errors returned at the storage boundary.
#[derive(Debug, Error)]
pub enum StoreError {
    /// The bounded runtime-dependency authority verifier refused an exact
    /// native record, chain, signature, scope, cut, or tuple.
    #[error(transparent)]
    RuntimeAuthority(#[from] nq_runtime_dependency_authority::AuthorityError),
    /// A SQLite operation failed.
    #[error("SQLite error: {0}")]
    Sqlite(#[from] rusqlite::Error),
    /// A filesystem operation failed.
    #[error("filesystem error: {0}")]
    Io(#[from] std::io::Error),
    /// Explicit initialization was required before opening the database.
    #[error("database is not initialized: {0}")]
    NotInitialized(PathBuf),
    /// Initialization never overwrites an existing SQLite schema.
    #[error("database already contains a schema (user_version {found_version})")]
    AlreadyInitialized { found_version: i64 },
    /// A database belongs to another application.
    #[error("database application id {found} is not nq-ng application id {expected}")]
    ApplicationIdMismatch { found: i64, expected: i64 },
    /// Runtime schema upgrades are forbidden.
    #[error("database schema version {found} is incompatible; this binary requires {supported}")]
    SchemaVersionMismatch { found: i64, supported: i64 },
    /// The database failed an integrity or schema invariant check.
    #[error("database integrity check failed: {0}")]
    Integrity(String),
    /// A document was not valid canonical JSON.
    #[error("canonical JSON error: {0}")]
    CanonicalJson(String),
    /// A core storage invariant was violated before SQL was attempted.
    #[error("storage invariant violated: {0}")]
    Invariant(String),
    /// A repeated provider attempt reused an identity for different evidence or
    /// a different bound context.
    #[error("provider intake replay conflict: {0}")]
    ReplayConflict(String),
    /// A sealed governed V3 projection must be recovered before this writer
    /// may allocate another publication identity.
    #[error("governed projection recovery required before publication: {0:?}")]
    GovernedProjectionRecoveryRequired(Vec<Sha256Digest>),
    /// Internal typed cause proving a deterministic mismatch between one exact
    /// sealed projection and exact available correspondence sources.
    ///
    /// Store transaction owners must roll back before converting this into the
    /// durable terminal refusal below.
    #[doc(hidden)]
    #[error("governed projection {reservation_record_id} failed exact correspondence: {reason}")]
    GovernedProjectionLocalCorrespondenceMismatch {
        reservation_record_id: Sha256Digest,
        reason: String,
    },
    /// Exact final bytes remain in custody, but deterministic projection
    /// correspondence failed and was durably terminalized.
    #[error(
        "governed projection {reservation_record_id} was durably refused by exact correspondence ({refusal_id}): {reason}"
    )]
    GovernedProjectionCorrespondenceRefused {
        reservation_record_id: Sha256Digest,
        refusal_id: Sha256Digest,
        reason: String,
    },
    /// The store generation is write-fenced: no session may be created and
    /// no session method may run.
    #[error("store writes are fenced: {0}")]
    WriteFenced(String),
    /// Another writer session for this store path is alive in this process;
    /// the process write lock is non-reentrant.
    #[error("writer session unavailable: {0}")]
    WriterSessionUnavailable(String),
    /// A rooted schema-v8 Store is missing its unique establishment receipt.
    #[error("runtime dependency trust root has no establishment receipt")]
    EstablishmentReceiptMissing,
    /// An establishment receipt exists without its corresponding root row.
    #[error("runtime dependency establishment receipt has no trust root")]
    EstablishmentRootMissing,
    /// Root/receipt state does not bind the Store's sole genesis occurrence.
    #[error("runtime dependency establishment occurrence does not match the sole Store genesis")]
    EstablishmentOccurrenceMismatch,
    /// Root and receipt bind different immutable anchors.
    #[error("runtime dependency establishment receipt does not match the immutable root anchor")]
    EstablishmentAnchorMismatch,
    /// Establishment-arm and migration-consumption custody disagree.
    #[error("runtime dependency establishment arm does not match migration receipt custody")]
    EstablishmentMigrationMismatch,
    /// A retained native authority carrier no longer hashes to its stored digest.
    #[error("runtime authority {family} record {record_id} has a canonical-byte digest mismatch")]
    AuthorityRecordDigestMismatch {
        family: &'static str,
        record_id: String,
    },
    /// A native authority row's SQL identity differs from its exact canonical
    /// record identity.
    #[error(
        "runtime authority {family} SQL identity {stored_record_id} differs from canonical identity {canonical_record_id}"
    )]
    AuthorityNativeRecordIdentityMismatch {
        family: &'static str,
        stored_record_id: String,
        canonical_record_id: Sha256Digest,
    },
    /// The retained establishment transcript no longer hashes to its stored digest.
    #[error("runtime dependency establishment receipt transcript digest mismatch")]
    EstablishmentTranscriptMismatch,
    /// A Gen4 operation requires exactly one nonempty Store genesis identity.
    #[error(
        "runtime authority operation requires exactly one nonempty genesis identity; found {found}"
    )]
    GenesisCardinality { found: u64 },
    /// The Store-owned complete native candidate set differs from the bounded
    /// evidence presented before the establishment transaction.
    #[error("runtime authority evidence does not bind the complete Store-resident candidate set")]
    AuthorityCandidateSetMismatch,
    /// The sealed evidence names an establishment arm incompatible with the
    /// exact Store state or schema transition.
    #[error("runtime authority establishment context does not match the Store state")]
    AuthorityEstablishmentContextMismatch,
    /// Fresh genesis establishment was attempted through a reopened,
    /// migrated, or already-consumed Store handle rather than the exact
    /// in-process handle returned by fresh storage initialization.
    #[error("runtime authority genesis requires the unconsumed fresh initialization handle")]
    AuthorityInitializationCandidateRequired,
    /// Schema-v7 migration was not opened through the backup-verified bounded
    /// migration source path.
    #[error("schema-v7 authority migration lacks its exact verified-source preflight")]
    AuthorityMigrationPreflightMissing,
    /// A repeated establishment differs from the immutable committed receipt.
    #[error("runtime authority establishment replay differs from the committed receipt")]
    AuthorityEstablishmentReplayConflict,
    /// The migration receipt's old rooted/rootless state differs from the
    /// locked pre-R2 Store.
    #[error("runtime authority migration receipt differs from the locked old-root state")]
    AuthorityMigrationOldRootMismatch,
    /// A declared restored Store has no unique, eligible proof closing its
    /// existing restore-quarantine law.
    #[error("runtime authority migration is refused by restored-Store quarantine")]
    AuthorityRestoreQuarantine,
    /// A verified native post-genesis event does not correspond to the exact
    /// Store set before or after append.
    #[error("verified runtime authority event does not correspond to the Store-resident set")]
    AuthorityEventCorrespondenceMismatch,
    /// A valid non-accepted migration disposition permanently evidence-froze
    /// this occurrence; no writer or establishment path may reactivate it.
    #[error("runtime authority occurrence is evidence-frozen by migration disposition {0}")]
    AuthorityEvidenceFrozen(String),
    /// The private C2 activation projection no longer corresponds to the
    /// complete Store-owned Gen4 authority snapshot and its sealed resolver
    /// result.
    #[error("C2 current activation does not correspond to the complete Gen4 authority resolution")]
    C2CurrentActivationCorrespondence,
    /// A C2-governed Store may obtain an ordinary writer session only through
    /// the closed-backend/current-activation HRTB path.
    #[error("C2 ordinary writer session requires exact closed-backend open correspondence")]
    C2OrdinaryOpenRequired,
    /// The private closed backend disagrees with one or more exact completed
    /// open coordinates or is no longer live under its retained lock.
    #[error("C2 completed ordinary-open inputs do not correspond")]
    C2CompletedOpenCorrespondence,
    /// A migration classification conflicts with an existing freeze fact.
    #[error("runtime authority migration classification conflicts with the retained freeze")]
    AuthorityMigrationDispositionConflict,
    /// An absent, singleton-empty, or multiple-genesis classification conflicts with its exact
    /// Store-derived cardinality, source, root, or retained carrier.
    #[error("runtime authority cardinality classification conflicts with the retained freeze")]
    AuthorityCardinalityDispositionConflict,
}

/// One immutable Store-side Gen4 establishment fact.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RuntimeDependencyEstablishmentReceipt {
    /// Chartered domain-separated receipt identity.
    pub receipt_id: Sha256Digest,
    /// Exact canonical, versioned authority transcript.
    pub transcript: EstablishmentReceiptTranscript,
    /// Store commit time; historical only and never a source of authority.
    pub established_at: String,
}

/// Durable result of a valid non-accepted migration classification.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RuntimeAuthorityMigrationFreezeReceipt {
    /// Exact signed migration receipt identity.
    pub migration_receipt_digest: Sha256Digest,
    /// Exact non-accepted disposition.
    pub disposition: MigrationDisposition,
    /// Exact Store occurrence frozen by the classification.
    pub occurrence_id: String,
    /// Store commit time; historical only and never authority.
    pub classified_at: String,
}

/// Durable result of an explicit absent, singleton-empty, or multiple-genesis disposition.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RuntimeAuthorityCardinalityFreezeReceipt {
    /// Exact operator-signed disposition identity.
    pub disposition_digest: Sha256Digest,
    /// Exact non-accepted disposition.
    pub disposition: MigrationDisposition,
    /// Number of exact Store genesis rows frozen (zero, one empty, or at least two).
    pub genesis_count: usize,
    /// Store commit time; historical only and never authority.
    pub classified_at: String,
}

/// Sealed declaration produced for an exact Store restored by the official
/// restore workflow.  It is a quarantine classifier, never authority.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RestoreDeclarationArtifact {
    /// Domain-separated identity of the exact declaration fields.
    pub declaration_digest: Sha256Digest,
    /// Canonical sidecar bytes to publish before the restored database.
    pub canonical_bytes: Vec<u8>,
    /// Exact physical digest of the restored Store named by the declaration.
    pub restored_store_sha256: Sha256Digest,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
struct RestoreDeclarationV1 {
    schema: String,
    declaration_digest: Sha256Digest,
    source_backup_sha256: Sha256Digest,
    restored_store_sha256: Sha256Digest,
    store_schema_version: i64,
    source_logical_digest: Option<Sha256Digest>,
    restored_logical_digest: Option<Sha256Digest>,
    grants_authority: bool,
}

#[derive(Serialize)]
struct RestoreDeclarationPreimage<'a> {
    domain: &'static str,
    schema: &'a str,
    source_backup_sha256: &'a Sha256Digest,
    restored_store_sha256: &'a Sha256Digest,
    store_schema_version: i64,
    source_logical_digest: Option<&'a Sha256Digest>,
    restored_logical_digest: Option<&'a Sha256Digest>,
    grants_authority: bool,
}

/// One coherent Store-owned read snapshot used only while ordinary runtime
/// authority resolution is executing.
pub(crate) struct RuntimeAuthorityRestartSnapshot {
    pub(crate) root: Sha256Digest,
    pub(crate) occurrence_id: String,
    pub(crate) receipt: RuntimeDependencyEstablishmentReceipt,
    pub(crate) presented: PresentedAuthoritySet,
    pub(crate) migration_receipt: Option<MigrationReceiptBytes>,
}

/// Store-owned input to the existing Gen4 restart resolver.
///
/// The value borrows one complete SQLite enumeration.  It has no public
/// constructor and deliberately implements neither serialization nor any
/// cloning/default trait.  In particular, a caller cannot replace the
/// complete candidate set with a digest or a filtered list.
pub(crate) struct CurrentActivationResolverInputV1<'snapshot> {
    root: &'snapshot Sha256Digest,
    occurrence_id: &'snapshot str,
    receipt: &'snapshot RuntimeDependencyEstablishmentReceipt,
    presented: &'snapshot PresentedAuthoritySet,
    migration_receipt: Option<&'snapshot MigrationReceiptBytes>,
    enumerated_set_digest: Sha256Digest,
}

impl CurrentActivationResolverInputV1<'_> {
    pub(crate) const fn root(&self) -> &Sha256Digest {
        self.root
    }

    pub(crate) const fn occurrence_id(&self) -> &str {
        self.occurrence_id
    }

    pub(crate) const fn receipt(&self) -> &RuntimeDependencyEstablishmentReceipt {
        self.receipt
    }

    pub(crate) const fn presented(&self) -> &PresentedAuthoritySet {
        self.presented
    }

    pub(crate) const fn migration_receipt(&self) -> Option<&MigrationReceiptBytes> {
        self.migration_receipt
    }

    pub(crate) const fn candidate_set_digest(&self) -> &Sha256Digest {
        &self.enumerated_set_digest
    }
}

/// Private borrowed projection of one already resolved Gen4 current A2.
///
/// This is applicability evidence only.  It is not A1 grant authority, C2
/// signer standing, backend closure, capacity, or a writer session.  Its
/// lifetime is bounded by the same Store-owned closure that holds the complete
/// enumeration and resolver output.
pub(crate) struct CurrentActivationForC2<'snapshot> {
    resolved: &'snapshot ControllingActivationSnapshot,
    enumerated_set_digest: &'snapshot Sha256Digest,
}

impl CurrentActivationForC2<'_> {
    pub(crate) fn occurrence_id(&self) -> &str {
        self.resolved.occurrence_id()
    }

    pub(crate) const fn controlling_tip_activation_digest(&self) -> &Sha256Digest {
        self.resolved.controlling_tip_activation_digest()
    }

    pub(crate) const fn chain_root_activation_digest(&self) -> &Sha256Digest {
        self.resolved.chain_root_activation_digest()
    }

    pub(crate) const fn trust_anchor_id(&self) -> &Sha256Digest {
        self.resolved.trust_anchor_id()
    }

    pub(crate) fn domain(&self) -> &str {
        self.resolved.domain()
    }

    pub(crate) fn resident_identity(&self) -> &str {
        self.resolved.resident_identity()
    }

    pub(crate) const fn resident_generation(&self) -> u64 {
        self.resolved.resident_generation()
    }

    pub(crate) fn host_role(&self) -> &str {
        self.resolved.host_role()
    }

    pub(crate) const fn role_manifest_generation(&self) -> u64 {
        self.resolved.role_manifest_generation()
    }

    pub(crate) const fn resolution_cut(&self) -> u64 {
        self.resolved.verification_cut().sequence()
    }

    /// Prove that this applicability view and another authority view borrow
    /// the same resolver result and the same complete Store enumeration.
    ///
    /// Equal values from a detached second resolution are deliberately
    /// insufficient: this is invocation-local provenance, not digest
    /// equivalence or a caller assertion.
    pub(crate) fn is_exact_projection_of(
        &self,
        input: &CurrentActivationResolverInputV1<'_>,
        resolved: &ControllingActivationSnapshot,
    ) -> bool {
        std::ptr::eq(self.resolved, resolved)
            && std::ptr::eq(self.enumerated_set_digest, input.candidate_set_digest())
    }

    pub(crate) const fn candidate_set_digest(&self) -> &Sha256Digest {
        self.enumerated_set_digest
    }

    pub(crate) const fn policy_version(&self) -> u64 {
        self.resolved.policy_version()
    }
}

/// N-08: collect the complete, unfiltered Gen4 authority ledger from the one
/// Store-owned read snapshot.  This performs no second parse or resolution.
pub(crate) fn collect_complete_gen4_authority_ledger(
    snapshot: &RuntimeAuthorityRestartSnapshot,
) -> Result<CurrentActivationResolverInputV1<'_>, StoreError> {
    let enumerated_set_digest = digest_presented_authority_set(&snapshot.presented)?;
    let input = CurrentActivationResolverInputV1 {
        root: &snapshot.root,
        occurrence_id: &snapshot.occurrence_id,
        receipt: &snapshot.receipt,
        presented: &snapshot.presented,
        migration_receipt: snapshot.migration_receipt.as_ref(),
        enumerated_set_digest,
    };
    verify_n_08_complete_gen4_authority_ledger(&input)?;
    Ok(input)
}

/// N-08 exact verifier.  The receipt is historical establishment evidence;
/// the current candidate-set digest is recomputed over every enumerated row.
pub(crate) fn verify_n_08_complete_gen4_authority_ledger(
    input: &CurrentActivationResolverInputV1<'_>,
) -> Result<(), StoreError> {
    if input.occurrence_id.is_empty()
        || input.receipt.transcript.occurrence_id() != input.occurrence_id
        || input.receipt.transcript.trust_anchor_id() != input.root
        || digest_presented_authority_set(input.presented)? != input.enumerated_set_digest
    {
        return Err(StoreError::C2CurrentActivationCorrespondence);
    }
    Ok(())
}

/// N-09: project only fields authenticated by the existing Gen4 resolver.
/// The sealed resolver result remains the sole source of current A2 standing.
pub(crate) fn project_current_activation_for_c2<'snapshot>(
    input: &'snapshot CurrentActivationResolverInputV1<'snapshot>,
    resolved: &'snapshot ControllingActivationSnapshot,
) -> Result<CurrentActivationForC2<'snapshot>, StoreError> {
    verify_n_08_complete_gen4_authority_ledger(input)?;
    if resolved.occurrence_id() != input.occurrence_id
        || resolved.trust_anchor_id() != input.root
        || resolved.candidate_set_digest() != &input.enumerated_set_digest
        || resolved.domain() != input.receipt.transcript.domain()
        || resolved.chain_root_activation_digest()
            != input.receipt.transcript.chain_root_activation_digest()
    {
        return Err(StoreError::C2CurrentActivationCorrespondence);
    }
    let activation = construct_current_activation_inside_complete_resolution(
        resolved,
        &input.enumerated_set_digest,
    );
    verify_n_09_current_activation_for_c2(&activation)?;
    Ok(activation)
}

/// The sole physical constructor for the borrowed C2 activation projection.
/// Its caller has already completed the exact Gen4 candidate-set resolution;
/// this helper cannot parse, resolve, filter, or clone authority evidence.
fn construct_current_activation_inside_complete_resolution<'snapshot>(
    resolved: &'snapshot ControllingActivationSnapshot,
    enumerated_set_digest: &'snapshot Sha256Digest,
) -> CurrentActivationForC2<'snapshot> {
    CurrentActivationForC2 {
        resolved,
        enumerated_set_digest,
    }
}

/// WU-09 named constructor.  It is only a thin, auditable alias for the sole
/// private projection above and never calls an authority parser or resolver.
pub(crate) fn construct_wu_09_immutable_wu_private_current_activation_handoff_ordinary<
    'snapshot,
>(
    input: &'snapshot CurrentActivationResolverInputV1<'snapshot>,
    resolved: &'snapshot ControllingActivationSnapshot,
) -> Result<CurrentActivationForC2<'snapshot>, StoreError> {
    project_current_activation_for_c2(input, resolved)
}

/// WU-09 exact current-activation verifier.
pub(crate) fn verify_wu_09_immutable_wu_private_current_activation_handoff_ordinary(
    activation: &CurrentActivationForC2<'_>,
) -> Result<(), StoreError> {
    verify_n_09_current_activation_for_c2(activation)
}

/// N-09 exact private-projection verifier.
pub(crate) fn verify_n_09_current_activation_for_c2(
    activation: &CurrentActivationForC2<'_>,
) -> Result<(), StoreError> {
    if activation.occurrence_id().is_empty()
        || activation
            .chain_root_activation_digest()
            .as_str()
            .is_empty()
        || activation
            .controlling_tip_activation_digest()
            .as_str()
            .is_empty()
        || activation.trust_anchor_id().as_str().is_empty()
        || activation.candidate_set_digest().as_str().is_empty()
        || activation.domain().is_empty()
        || activation.resident_identity().is_empty()
        || activation.resident_generation() == 0
        || activation.host_role().is_empty()
        || activation.role_manifest_generation() == 0
        || activation.policy_version() == 0
        || activation.resolution_cut() == 0
    {
        return Err(StoreError::C2CurrentActivationCorrespondence);
    }
    Ok(())
}

/// N-49 named row witness.  Returning the original invocation-borrowed value
/// proves no clone, serialization, default, or public snapshot conversion is
/// involved.
pub(crate) fn construct_n_49_currentactivationforc2_is_private_borrowed_nonserializable_default_same<
    'a,
>(
    activation: &'a CurrentActivationForC2<'a>,
) -> Result<&'a CurrentActivationForC2<'a>, StoreError> {
    verify_n_09_current_activation_for_c2(activation)?;
    Ok(activation)
}

/// N-49 exact verifier.
pub(crate) fn verify_n_49_currentactivationforc2_is_private_borrowed_nonserializable_default_same(
    activation: &CurrentActivationForC2<'_>,
) -> Result<(), StoreError> {
    verify_n_09_current_activation_for_c2(activation)
}

/// N-50 exact verifier.  The only accepted value is the private projection;
/// there is no raw snapshot, digest-only, A2-only, or second-parser overload.
pub(crate) fn verify_n_50_refusal(
    activation: &CurrentActivationForC2<'_>,
) -> Result<(), StoreError> {
    verify_n_09_current_activation_for_c2(activation)
}

/// P-06 exact completed-open inputs.  Every field is borrowed and private;
/// the value cannot outlive either current activation or the sole closed
/// backend and contains no independently mintable Boolean standing.
pub(crate) struct CompletedC2OpenInputsV1<'activation, 'backend> {
    current_activation: &'activation CurrentActivationForC2<'activation>,
    occurrence: &'backend store_generation::records::StoreOccurrenceIdentityV1,
    physical_generation: &'backend store_generation::records::PhysicalStoreGenerationIdentityV1,
    active_policy: &'backend Sha256Digest,
    closed_backend: &'backend capacity_backend::ClosedC2StoreBackendV1<'backend>,
}

impl<'activation, 'backend> CompletedC2OpenInputsV1<'activation, 'backend> {
    fn new_verified(
        current_activation: &'activation CurrentActivationForC2<'activation>,
        occurrence: &'backend store_generation::records::StoreOccurrenceIdentityV1,
        physical_generation: &'backend store_generation::records::PhysicalStoreGenerationIdentityV1,
        active_policy: &'backend Sha256Digest,
        closed_backend: &'backend capacity_backend::ClosedC2StoreBackendV1<'backend>,
    ) -> Self {
        Self {
            current_activation,
            occurrence,
            physical_generation,
            active_policy,
            closed_backend,
        }
    }

    fn begin<R>(
        self,
        store: &mut Store,
        operation: impl for<'session> FnOnce(&mut StoreWriterSession<'session>) -> Result<R, StoreError>,
    ) -> Result<R, StoreError> {
        let mut session =
            writer_session::construct_n_60_ordinary_session_requires_closed_state_process_mutex(
                store,
                self.closed_backend,
                self.occurrence,
                self.physical_generation,
            )?;
        operation(&mut session)
    }
}

/// P-06 verifies current activation and the already closed backend against the
/// same exact occurrence, physical generation, and active policy coordinates.
pub(crate) fn verify_completed_c2_open_inputs(
    current_activation: &CurrentActivationForC2<'_>,
    occurrence: &store_generation::records::StoreOccurrenceIdentityV1,
    physical_generation: &store_generation::records::PhysicalStoreGenerationIdentityV1,
    active_policy: &Sha256Digest,
    closed_backend: &capacity_backend::ClosedC2StoreBackendV1<'_>,
) -> Result<(), StoreError> {
    verify_n_09_current_activation_for_c2(current_activation)?;
    if current_activation.occurrence_id() != occurrence.as_str()
        || physical_generation.digest().as_str().is_empty()
        || active_policy.as_str().is_empty()
    {
        return Err(StoreError::C2CompletedOpenCorrespondence);
    }
    capacity_backend::verify_closed_backend_current_activation_coordinates_v1(
        closed_backend,
        occurrence,
        physical_generation,
        active_policy,
    )
    .map_err(|_| StoreError::C2CompletedOpenCorrespondence)
}

/// A canonical JSON document and its SHA-256 semantic digest.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct CanonicalDocument {
    bytes: Vec<u8>,
    digest: String,
}

impl CanonicalDocument {
    /// Canonicalize a serializable value with the authoritative protocol routine.
    pub fn from_serializable<T: Serialize>(value: &T) -> Result<Self, StoreError> {
        let bytes = nq_protocol::canonical_json_bytes(value)
            .map_err(|error| StoreError::CanonicalJson(error.to_string()))?;
        validate_document_size(bytes.len())?;
        let digest = sha256_digest(&bytes);
        Ok(Self { bytes, digest })
    }

    /// Accept bytes only when they are already in canonical protocol form.
    pub fn from_canonical_bytes(bytes: Vec<u8>) -> Result<Self, StoreError> {
        validate_document_size(bytes.len())?;
        let value: Value = serde_json::from_slice(&bytes)
            .map_err(|error| StoreError::CanonicalJson(error.to_string()))?;
        let expected = nq_protocol::canonical_json_bytes(&value)
            .map_err(|error| StoreError::CanonicalJson(error.to_string()))?;
        if expected != bytes {
            return Err(StoreError::CanonicalJson(
                "document bytes are valid JSON but not canonical".to_owned(),
            ));
        }
        let digest = sha256_digest(&bytes);
        Ok(Self { bytes, digest })
    }

    /// Return the exact canonical bytes persisted by the store.
    #[must_use]
    pub fn as_bytes(&self) -> &[u8] {
        &self.bytes
    }

    /// Return the lowercase SHA-256 digest of the canonical bytes.
    #[must_use]
    pub fn digest(&self) -> &str {
        &self.digest
    }
}

