    #[test]
    fn gen4_verified_authority_events_are_family_resident_and_restart_resolved() {
        let directory = tempdir().expect("authority event directory");
        let database = directory.path().join("authority-events.sqlite");
        let mut store =
            Store::initialize_runtime_authority_candidate(&database).expect("authority Store");
        let mut fixture = RawAuthorityFixture::fresh_genesis();
        establish_authority_fixture(&mut store, &fixture).expect("authority establishment");
        let custody = fixture.custody();
        let expectations = fixture.activation_expectations();

        let current = store
            .runtime_authority_presented_set()
            .expect("empty current set");
        let successor = fixture.append_activation_successor();
        store
            .with_runtime_authority_writer_session(|brand, session| {
                let verified = verify_resident_activation_successor(
                    brand,
                    &custody,
                    &current,
                    &successor,
                    None,
                    &expectations,
                )?;
                session.append_runtime_resident_activation_successor(&verified)
            })
            .expect("append verified A2 successor");

        let current = store
            .runtime_authority_presented_set()
            .expect("successor set");
        let rotation = fixture.append_operator_rotation();
        store
            .with_runtime_authority_writer_session(|brand, session| {
                let verified = verify_operator_authority_rotation(
                    brand,
                    &custody,
                    &current,
                    &rotation,
                    None,
                    &expectations,
                )?;
                session.append_runtime_operator_authority_rotation(&verified)
            })
            .expect("append verified A1 rotation after resident successor");

        let current = store
            .runtime_authority_presented_set()
            .expect("cross-family successor and rotation set");
        let snapshot =
            resolve_for_restart(&custody, &current, None, &fixture.restart_expectations())
                .expect("restart resolves successor");
        assert_eq!(
            snapshot.controlling_tip_activation_digest(),
            fixture.current_activation_digest()
        );

        let revocation = fixture.append_current_activation_revocation();
        store
            .with_runtime_authority_writer_session(|brand, session| {
                let verified = verify_activation_revocation(
                    brand,
                    &custody,
                    &current,
                    &revocation,
                    None,
                    &expectations,
                )?;
                session.append_runtime_activation_revocation(&verified)
            })
            .expect("append verified revocation");
        let stored = store
            .runtime_authority_presented_set()
            .expect("complete set");
        assert_eq!(stored.records().len(), 3);
        assert!(matches!(
            resolve_for_restart(&custody, &stored, None, &fixture.restart_expectations()),
            Err(nq_runtime_dependency_authority::AuthorityError::ControllingActivationRevoked)
        ));

        let successor_after_revocation = fixture.append_activation_successor();
        store
            .with_runtime_authority_writer_session(|brand, session| {
                let verified = verify_resident_activation_successor(
                    brand,
                    &custody,
                    &stored,
                    &successor_after_revocation,
                    None,
                    &expectations,
                )?;
                session.append_runtime_resident_activation_successor(&verified)
            })
            .expect("append verified successor after resident revocation");
        let stored = store
            .runtime_authority_presented_set()
            .expect("complete cross-family set");
        assert!(matches!(
            stored.records(),
            [
                PresentedAuthorityRecord::OperatorAuthorityRotation(_),
                PresentedAuthorityRecord::ResidentActivationSuccessor(_),
                PresentedAuthorityRecord::ResidentActivationSuccessor(_),
                PresentedAuthorityRecord::ActivationRevocation(_),
            ]
        ));
        store
            .validate()
            .expect("native authority families validate structurally");
        drop(store);

        let mut reopened = Store::open(&database).expect("reopen authority Store");
        let resolved = reopened
            .with_runtime_authority_restart_snapshot(|snapshot| -> Result<_, StoreError> {
                resolve_for_restart(
                    &custody,
                    &snapshot.presented,
                    snapshot.migration_receipt.as_ref(),
                    &fixture.restart_expectations(),
                )
                .map_err(StoreError::from)
            })
            .expect("Store-backed restart resolves post-revocation successor");
        assert_eq!(
            resolved.controlling_tip_activation_digest(),
            fixture.current_activation_digest()
        );
    }

    #[test]
    fn c2_terminal_a1_projection_is_same_snapshot_and_adjacency_selected() {
        let mut store = Store::initialize_runtime_authority_candidate_in_memory()
            .expect("terminal A1 projection Store");
        let mut fixture = RawAuthorityFixture::fresh_genesis();
        establish_authority_fixture(&mut store, &fixture).expect("establish authority");
        let custody = fixture.custody();
        let expectations = fixture.activation_expectations();

        for _ in 0..2 {
            let current = store
                .runtime_authority_presented_set()
                .expect("complete predecessor set");
            let rotation = fixture.append_operator_rotation();
            store
                .with_runtime_authority_writer_session(|brand, session| {
                    let verified = verify_operator_authority_rotation(
                        brand,
                        &custody,
                        &current,
                        &rotation,
                        None,
                        &expectations,
                    )?;
                    session.append_runtime_operator_authority_rotation(&verified)
                })
                .expect("append adjacent A1 rotation");
        }

        let current = store
            .runtime_authority_presented_set()
            .expect("two-rotation predecessor set");
        let successor = fixture.append_activation_successor();
        store
            .with_runtime_authority_writer_session(|brand, session| {
                let verified = verify_resident_activation_successor(
                    brand,
                    &custody,
                    &current,
                    &successor,
                    None,
                    &expectations,
                )?;
                session.append_runtime_resident_activation_successor(&verified)
            })
            .expect("append later A2 event");

        store
            .with_runtime_authority_restart_snapshot(|snapshot| -> Result<(), StoreError> {
                let input = collect_complete_gen4_authority_ledger(&snapshot)?;
                let resolved = resolve_for_restart(
                    &custody,
                    &snapshot.presented,
                    snapshot.migration_receipt.as_ref(),
                    &fixture.restart_expectations(),
                )?;
                let terminal = store_generation::signer::authority::construct_sg_n_03_issuer_currentness_is_resolved_complete_store_owned(
                    &input,
                    &resolved,
                )
                .map_err(|_| StoreError::C2CurrentActivationCorrespondence)?;
                store_generation::signer::authority::verify_sg_n_03_issuer_currentness_is_resolved_complete_store_owned(
                    &terminal,
                )
                .map_err(|_| StoreError::C2CurrentActivationCorrespondence)?;

                assert_eq!(terminal.terminal().key_generation(), 3);
                assert_eq!(
                    terminal.terminal().record_digest(),
                    resolved.terminal_operator_authority().record_digest()
                );
                assert_eq!(
                    terminal.issuance_cut(),
                    resolved.verification_cut().sequence()
                );
                assert!(terminal.terminal().cut().sequence() < terminal.issuance_cut());
                assert_eq!(
                    terminal.controlling_activation(),
                    resolved.controlling_tip_activation_digest()
                );

                let issuer = store_generation::signer::authority::construct_sg_n_02_bootstrap_grant_issuer_is_exactly_resolver_selected(
                    &terminal,
                    [0x55; 32],
                )
                .expect("derive terminal A1 bootstrap issuer");
                store_generation::signer::authority::verify_sg_n_02_bootstrap_grant_issuer_is_exactly_resolver_selected(
                    &issuer,
                    &terminal,
                    [0x55; 32],
                )
                .expect("verify exact terminal A1 bootstrap issuer");
                assert_eq!(issuer.key_generation(), 3);
                assert_eq!(issuer.record_digest(), terminal.terminal().record_digest());
                assert_eq!(issuer.issuance_cut(), terminal.issuance_cut());
                assert_eq!(issuer.terminal_a1_cut(), terminal.terminal().cut().sequence());

                assert!(matches!(
                    store_generation::signer::authority::construct_sg_n_02_bootstrap_grant_issuer_is_exactly_resolver_selected(
                        &terminal,
                        *terminal.terminal().verification_key(),
                    ),
                    Err(store_generation::signer::result::SignerRefusalV2::IssuerSignerKeyCollision)
                ));

                let mut reordered_records = snapshot.presented.records().to_vec();
                reordered_records.reverse();
                let reordered = PresentedAuthoritySet::new(reordered_records);
                let reordered_digest = digest_presented_authority_set(&reordered)?;
                let reordered_input = CurrentActivationResolverInputV1 {
                    root: &snapshot.root,
                    occurrence_id: &snapshot.occurrence_id,
                    receipt: &snapshot.receipt,
                    presented: &reordered,
                    migration_receipt: snapshot.migration_receipt.as_ref(),
                    enumerated_set_digest: reordered_digest,
                };
                assert!(matches!(
                    store_generation::signer::authority::construct_sg_n_03_issuer_currentness_is_resolved_complete_store_owned(
                        &reordered_input,
                        &resolved,
                    ),
                    Err(store_generation::signer::result::SignerRefusalV2::WrongTerminalA1Issuer)
                ));

                let prefix = PresentedAuthoritySet::new(
                    snapshot.presented.records()[..2].to_vec(),
                );
                let prefix_digest = digest_presented_authority_set(&prefix)?;
                let prefix_input = CurrentActivationResolverInputV1 {
                    root: &snapshot.root,
                    occurrence_id: &snapshot.occurrence_id,
                    receipt: &snapshot.receipt,
                    presented: &prefix,
                    migration_receipt: snapshot.migration_receipt.as_ref(),
                    enumerated_set_digest: prefix_digest,
                };
                assert!(matches!(
                    store_generation::signer::authority::construct_sg_n_03_issuer_currentness_is_resolved_complete_store_owned(
                        &prefix_input,
                        &resolved,
                    ),
                    Err(store_generation::signer::result::SignerRefusalV2::WrongTerminalA1Issuer)
                ));
                Ok(())
            })
            .expect("project exact terminal A1 from complete Store snapshot");
    }

    #[test]
    fn gen4_restart_snapshot_is_coherent_across_each_native_family_write_race() {
        let directory = tempdir().expect("restart snapshot race directory");
        for (label, table, family) in [
            ("operator", "runtime_operator_authority_rotations", 0_u8),
            ("activation", "runtime_resident_activation_successors", 1_u8),
            ("revocation", "runtime_activation_revocations", 2_u8),
        ] {
            let database = directory.path().join(format!("restart-race-{label}.db"));
            let mut store = Store::initialize_runtime_authority_candidate(&database)
                .expect("race authority candidate");
            store
                .connection
                .pragma_update(None, "journal_mode", "WAL")
                .expect("enable WAL for concurrent restart snapshot fixture");
            let mut fixture = RawAuthorityFixture::fresh_genesis();
            establish_authority_fixture(&mut store, &fixture).expect("race establishment");
            let bytes = match family {
                0 => fixture.append_operator_rotation(),
                1 => fixture.append_activation_successor(),
                2 => fixture.append_current_activation_revocation(),
                _ => unreachable!("closed native authority family"),
            };
            let record_id = native_authority_record_id(family, &bytes);
            let database_for_hook = database.clone();

            let snapshot_count = store
                .with_runtime_authority_restart_snapshot_test_hook(
                    || -> Result<(), StoreError> {
                        let connection = Connection::open(&database_for_hook)?;
                        connection.busy_timeout(std::time::Duration::from_secs(5))?;
                        insert_native_authority_record(&connection, table, &record_id, &bytes)
                    },
                    |snapshot| -> Result<usize, StoreError> {
                        assert_eq!(snapshot.occurrence_id, FIXTURE_OCCURRENCE_ID);
                        Ok(snapshot.presented.records().len())
                    },
                )
                .expect("coherent restart snapshot");
            assert_eq!(
                snapshot_count, 0,
                "{label} write leaked into an already-established read snapshot"
            );
            assert_eq!(
                store
                    .runtime_authority_presented_set()
                    .expect("post-race Store enumeration")
                    .records()
                    .len(),
                1,
                "{label} write was not visible after releasing the read snapshot"
            );
        }
    }

    #[test]
    fn gen4_stale_verified_event_refuses_after_store_reenumeration_without_appending() {
        let directory = tempdir().expect("stale evidence directory");
        let database = directory.path().join("stale-evidence.db");
        let mut store = Store::initialize_runtime_authority_candidate(&database)
            .expect("authority candidate Store");
        let base = RawAuthorityFixture::fresh_genesis();
        establish_authority_fixture(&mut store, &base).expect("authority establishment");

        let current = store.runtime_authority_presented_set().expect("empty set");
        let mut proposed_fixture = RawAuthorityFixture::fresh_genesis();
        let proposed = proposed_fixture.append_activation_successor();
        let mut interloper_fixture = RawAuthorityFixture::fresh_genesis();
        let interloper = interloper_fixture.append_operator_rotation();
        let parsed_interloper = OperatorAuthorityRecord::from_canonical_bytes(&interloper)
            .expect("interloper A1 record");
        let interloper_id = parsed_interloper.record_digest().clone();
        let custody = proposed_fixture.custody();
        let expectations = proposed_fixture.activation_expectations();
        let database_for_interloper = database.clone();

        let result = store.with_runtime_authority_writer_session(|brand, session| {
            let verified = verify_resident_activation_successor(
                brand,
                &custody,
                &current,
                &proposed,
                None,
                &expectations,
            )?;
            let interloper_connection = Connection::open(&database_for_interloper)?;
            interloper_connection.execute(
                "INSERT INTO runtime_operator_authority_rotations (
                    record_id, canonical_bytes, canonical_bytes_sha256,
                    canonical_bytes_length, committed_at
                 ) VALUES (?1, ?2, ?3, ?4, ?5)",
                params![
                    interloper_id.as_str(),
                    interloper,
                    sha256_bytes(&interloper).as_str(),
                    i64::try_from(interloper.len()).expect("interloper length"),
                    TIME,
                ],
            )?;
            drop(interloper_connection);
            session.append_runtime_resident_activation_successor(&verified)
        });
        assert!(matches!(
            result,
            Err(StoreError::AuthorityEventCorrespondenceMismatch)
        ));
        let counts = store
            .connection
            .query_row(
                "SELECT
                    (SELECT COUNT(*) FROM runtime_operator_authority_rotations),
                    (SELECT COUNT(*) FROM runtime_resident_activation_successors)",
                [],
                |row| Ok((row.get::<_, i64>(0)?, row.get::<_, i64>(1)?)),
            )
            .expect("stale evidence counts");
        assert_eq!(counts, (1, 0));
        resolve_for_restart(
            &interloper_fixture.custody(),
            &store
                .runtime_authority_presented_set()
                .expect("stored interloper"),
            None,
            &interloper_fixture.restart_expectations(),
        )
        .expect("interloper is the sole complete Store history");
    }

